    tmp_image_tk = ImageTk.PhotoImage(final_image)
    myGlobals.label_image.configure(image=tmp_image_tk)
    myGlobals.label_image.image = tmp_image_tk # keep a reference!


#    update_info()



def show_initial_preview_window():
