	private String hexDump(int start, int length) {
		byte[] dump = new byte[length];
		for (int i = 0; i < length; i++) {
			dump[i] = mem.read(start + i).signedByte();
		}
		return ByteArrayPrettyPrinter.spaceSeparatedHex(dump);
	}

