	public C64Simulator tick() {
		List<Debug> debugs = debugsByAddr.get(pc.value());
		if (debugs != null) {
			for (Debug debug : debugs) {
				debug.execute(debugContext);
			}
		}
		time++;
		listener.timeAdvanced(time);
		instr.tick();
		return this;
	}

	public C64Simulator tick(int cycles) {
		for (int i = 0; i < cycles; i++) {
