			UnsignedByte argLsb = readMem(pc.plus(1));
			UnsignedByte argMsb = readMem(pc.plus(2));
			RawAddress arg = RawAddress.fromLsbAndMsb(argLsb, argMsb);

			UnsignedByte refLsb = readMem(arg);
