	private UnsignedByte lsr(UnsignedByte orig) {
		UnsignedByte result = UnsignedByte.from(orig.uInt() / 2);
		sr().setCarry(!orig.and(UnsignedByte.x01).isZero());
		sr().setNegative(result.isNegative());
		sr().setZero(result.isZero());
		return result;
	}

