		int newValue = value.uInt() * 2 + sr().carryAsZeroOrOne();
		UnsignedByte newByte = UnsignedByte.fromLsbOf(newValue);
		sr().setZero(newByte.isZero());
		sr().setNegative(newByte.isNegative());
		sr().setCarry(newValue > 255);
		return newByte;
