	private UnsignedByte aslUpdatingSr(UnsignedByte src) {
		UnsignedByte shifted = UnsignedByte.fromLsbOf(src.uInt() << 1);
		sr().setCarry(src.isBit7());
		sr().setNegative(shifted.isBit7());
		sr().setZero(shifted.equals(UnsignedByte.x00));
		return shifted;
	}

