		@Override
		void result() {
			writeSr(popByte());
			// write to zero and negative were already notified by writeSr
			// above, so let's notify the rest:
			// (TODO Fix the design, we should not know about the listene here)
			sr.listener.writeStatusC(sr, sr.carry());
			sr.listener.writeStatusV(sr, sr.overflow());
		}

	}

	private class Bmi extends RelativeInstrInstance {

		Bmi() {
			super(Op.BMI);
		}

		@Override
		void result() {
			if (sr.negative()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bpl extends RelativeInstrInstance {

		Bpl() {
			super(Op.BPL);
		}

		@Override
		void result() {
			if (!sr.negative()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bcc extends RelativeInstrInstance {

		Bcc() {
			super(Op.BCC);
		}

		@Override
		void result() {
			if (!sr.carry()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bcs extends RelativeInstrInstance {

		Bcs() {
			super(Op.BCS);
		}

		@Override
		void result() {
			if (sr.carry()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bvc extends RelativeInstrInstance {

		Bvc() {
			super(Op.BVC);
		}

		@Override
		void result() {
			if (!sr.overflow()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bvs extends RelativeInstrInstance {

		Bvs() {
			super(Op.BVS);
		}

		@Override
		void result() {
			if (sr.overflow()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Beq extends RelativeInstrInstance {

		Beq() {
			super(Op.BEQ);
		}

		@Override
		void result() {
			if (sr.zero()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class Bne extends RelativeInstrInstance {

		Bne() {
			super(Op.BNE);
		}

		@Override
		void result() {
			if (!sr.zero()) {
				setPc(operand());
			} else {
				advanceToNextInstr();
			}
		}

	}

	private class SbcAbs extends AbsInstrInstance {

		SbcAbs() {
			super(Op.SBC_ABS);
		}

		@Override
		void result() {
			UnsignedByte termValue = readMem(operand());
			sbc(termValue, true);
		}

	}

	private void sbc(UnsignedByte termValue, boolean updateV) {
		sbc(termValue, a(), updateV);
	}

	private void sbc(UnsignedByte termValue, Register reg, boolean updateV) {
		addToReg(termValue.eor(UnsignedByte.xFF), reg, updateV);
	}

}

